:root {
  --color-bg: #f5f5f7;
  --color-surface: #ffffff;
  --color-primary: #1d6bf3;
  --color-primary-hover: #1558d6;
  --color-primary-active: #1047b8;
  --color-text: #1a1a2e;
  --color-text-muted: #6b7280;
  --color-border: #d1d5db;
  --color-border-focus: #1d6bf3;
  --color-radio-selected: #1d6bf3;
  --color-radio-hover-bg: #eff4ff;
  --color-error: #dc2626;
  --color-success: #16a34a;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --shadow-card: 0 1px 3px rgba(0,0,0,.08), 0 8px 24px rgba(0,0,0,.06);
  --shadow-btn: 0 1px 2px rgba(29,107,243,.25), 0 4px 12px rgba(29,107,243,.18);
  --transition: 150ms ease;
  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

body {
  font-family: var(--font);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  line-height: 1.5;
}

/* ── Skip link ─────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -999px;
  left: 8px;
  background: var(--color-primary);
  color: #fff;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus {
  top: 8px;
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

/* ── Page chrome ────────────────────────────────────── */
.page-header {
  width: 100%;
  max-width: 480px;
  margin-bottom: 8px;
  text-align: center;
}

.page-header__eyebrow {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--color-primary);
  background: rgba(29,107,243,.08);
  padding: 4px 10px;
  border-radius: 999px;
  margin-bottom: 12px;
}

.page-header__title {
  font-size: clamp(22px, 5vw, 28px);
  font-weight: 700;
  letter-spacing: -.4px;
  line-height: 1.25;
  margin-bottom: 8px;
}

.page-header__subtitle {
  font-size: 15px;
  color: var(--color-text-muted);
}

/* ── Card ───────────────────────────────────────────── */
.card {
  width: 100%;
  max-width: 480px;
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 32px;
  margin-top: 20px;
}

/* ── Form field wrapper ─────────────────────────────── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.form-field__legend {
  font-size: 15px;
  font-weight: 600;
  color: var(--color-text);
  padding: 0;
}

.form-field__hint {
  font-size: 13px;
  color: var(--color-text-muted);
  margin-top: -4px;
}

/* ── Radio group ────────────────────────────────────── */
.radio-group {
  display: flex;
  flex-direction: column;
  gap: 10px;
  list-style: none;
  padding: 0;
  margin: 0;
}

/* Each radio item is a <label> wrapping a hidden <input> + visual indicator */
.radio-option {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition:
    border-color var(--transition),
    background var(--transition),
    box-shadow var(--transition);
  position: relative;
  user-select: none;
}

.radio-option:hover {
  border-color: var(--color-radio-selected);
  background: var(--color-radio-hover-bg);
}

/* Hidden native input — still in flow for keyboard / AT */
.radio-option__input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
  pointer-events: none;
}

/* Custom radio circle */
.radio-option__circle {
  width: 20px;
  height: 20px;
  min-width: 20px;
  border-radius: 50%;
  border: 2px solid var(--color-border);
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  transition:
    border-color var(--transition),
    background var(--transition);
}

.radio-option__circle::after {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #fff;
  opacity: 0;
  transform: scale(0.5);
  transition: opacity var(--transition), transform var(--transition);
}

/* Checked state */
.radio-option__input:checked ~ .radio-option__body .radio-option__circle,
.radio-option:has(.radio-option__input:checked) .radio-option__circle {
  border-color: var(--color-radio-selected);
  background: var(--color-radio-selected);
}

.radio-option:has(.radio-option__input:checked) .radio-option__circle::after {
  opacity: 1;
  transform: scale(1);
}

.radio-option:has(.radio-option__input:checked) {
  border-color: var(--color-radio-selected);
  background: var(--color-radio-hover-bg);
}

/* Focus-visible ring on the label */
.radio-option:has(.radio-option__input:focus-visible) {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

/* Option text */
.radio-option__body {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
}

.radio-option__icon {
  font-size: 20px;
  line-height: 1;
  flex-shrink: 0;
  /* Icons are decorative — aria-hidden in HTML */
}

.radio-option__label-text {
  font-size: 15px;
  font-weight: 500;
  color: var(--color-text);
}

.radio-option__desc {
  font-size: 12px;
  color: var(--color-text-muted);
  margin-top: 1px;
}

/* ── Validation message ─────────────────────────────── */
.validation-message {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 500;
  color: var(--color-error);
  padding: 0 2px;
  min-height: 20px;
}

.validation-message[hidden] {
  display: none;
}

/* ── Divider ─────────────────────────────────────────── */
.divider {
  height: 1px;
  background: var(--color-border);
  margin: 24px 0;
  border: none;
}

/* ── Submit button ──────────────────────────────────── */
.btn-submit {
  width: 100%;
  padding: 14px 24px;
  background: var(--color-primary);
  color: #fff;
  font-family: var(--font);
  font-size: 15px;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  box-shadow: var(--shadow-btn);
  transition:
    background var(--transition),
    box-shadow var(--transition),
    transform 80ms ease;
  letter-spacing: .01em;
}

.btn-submit:hover {
  background: var(--color-primary-hover);
}

.btn-submit:active {
  background: var(--color-primary-active);
  transform: translateY(1px);
  box-shadow: none;
}

.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

/* ── Success banner (shown after submit) ───────────── */
.success-banner {
  display: none;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  background: #f0fdf4;
  border: 1.5px solid #bbf7d0;
  border-radius: var(--radius-md);
  color: var(--color-success);
  font-size: 14px;
  font-weight: 500;
  margin-top: 16px;
}

.success-banner.visible {
  display: flex;
}

.success-banner__icon {
  font-size: 18px;
  flex-shrink: 0;
}

/* ── Forced colors ──────────────────────────────────── */
@media (forced-colors: active) {
  .radio-option {
    border-color: ButtonBorder;
    color: ButtonText;
  }

  .radio-option:has(.radio-option__input:checked) {
    border-color: Highlight;
    background: Canvas;
  }

  .radio-option__circle {
    border-color: ButtonBorder;
  }

  .radio-option:has(.radio-option__input:checked) .radio-option__circle {
    border-color: Highlight;
    background: Highlight;
    forced-color-adjust: none;
  }

  .radio-option:has(.radio-option__input:checked) .radio-option__circle::after {
    background: HighlightText;
  }

  .btn-submit {
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonBorder;
    box-shadow: none;
    forced-color-adjust: none;
  }
}

/* ── Reduced motion ─────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0ms !important;
    animation-duration: 0ms !important;
  }
}

/* ── Reflow / small viewport ────────────────────────── */
@media (max-width: 380px) {
  .card {
    padding: 24px 20px;
  }
}
