  fragment.appendChild(skipLink);

  // Page header
  const header = el("header", { class: "page-header", role: "banner" }, [
    el("span", { class: "page-header__eyebrow" }, ["Preferences"]),
    el("h1", { class: "page-header__title" }, ["Account Settings"]),
